package dev.docweave.layout;
import java.awt.image.BufferedImage;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Arrays;
public final class CheckResolution {
 public static void main(String[] args) throws Exception {
  var image = new BufferedImage(17,29,BufferedImage.TYPE_INT_ARGB);
  for (int y=0;y<29;y++) for(int x=0;x<17;x++) image.setRGB(x,y,0x80000000 | x*1000+y*17);
  var before = image.getRGB(0,0,17,29,null,0,17);
  var options=OnnxTableOptions.defaults(Path.of("unused.onnx"),"0".repeat(64));
  var base=new BilinearTableImageTransform().prepare(image,options,new LayoutDeadline(Duration.ofSeconds(30)));
  var trial=new ExperimentalDetectorTransform().prepare(image,options,new LayoutDeadline(Duration.ofSeconds(30)));
  if (Math.max(base.width(),base.height())!=800 || Math.max(trial.width(),trial.height())!=1200) throw new AssertionError("Unexpected transform dimensions");
  if (trial.sourceWidth()!=17 || trial.sourceHeight()!=29) throw new AssertionError("Source frame changed");
  if (!Arrays.equals(before,image.getRGB(0,0,17,29,null,0,17))) throw new AssertionError("Source pixels changed");
  System.out.println("Verified max800/max1200, preserved source frame and pixels");
 }
}
